<script setup>
import { demoTimezones, readDemoSettings, validDemoRetention } from '../../ui-demo/demo-settings';
import componentPages from '../../ui-demo/component-pages.json';
import ComponentExperience from './ComponentExperience.vue';
import { computed, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useToast } from 'primevue/usetoast';
import { tasks, resources, logs, services, runDemoTask } from '../../ui-demo/data';
import { isDarkTheme } from './theme';
const route = useRoute(); const router = useRouter(); const toast = useToast();
const query = ref(''); const filter = ref('all'); const createOpen = ref(false); const uploadOpen = ref(false); const selected = ref(null); const previewOpen = ref(false); const errors = ref('');
const draft = reactive({ name:'', app:'demo-api', schedule:'每天 09:00' });
const settings = reactive(readDemoSettings('workerkit-prime-settings'));
const names = { '/':'运行概览', '/tasks':'任务调度', '/logs':'运行日志', '/settings':'应用设置' };
const descriptions = { '/':'从这里了解应用状态、任务执行与资源使用情况。', '/tasks':'管理自动化计划，查看执行状态，随时手动运行。', '/logs':'按应用和级别查看执行事件，快速定位异常。', '/settings':'配置工作空间、显示偏好和通知选项。' };
const componentPage = computed(() => componentPages.find(page => page.path === route.path));
const activePath = computed(() => componentPage.value?.example || route.path);
Object.assign(names, Object.fromEntries(componentPages.map(page => [page.path, page.title])));
Object.assign(descriptions, Object.fromEntries(componentPages.map(page => [page.path, page.description])));
watch(() => route.path, () => { query.value='';filter.value='all'; document.title=`WorkerKit · ${names[route.path]} · ${__PRIMEVUE_LIBRARY__ ? 'PrimeVue' : 'Sakai'}`; }, { immediate:true });
const statuses = { success:['成功','success'], warning:['部分失败','warn'], paused:['已暂停','secondary'], running:['运行中','info'] };
const types = { image:['图片','pi-image'], audio:['音频','pi-volume-up'], video:['视频','pi-video'], document:['文档','pi-file'] };
const filteredTasks = computed(() => tasks.value.filter(t => `${t.name} ${t.app}`.includes(query.value) && (filter.value==='all' || (filter.value==='enabled'?t.enabled:!t.enabled))));
const filteredResources = computed(() => resources.value.filter(r => r.name.includes(query.value) && (filter.value==='all'||r.type===filter.value)));
const filteredLogs = computed(() => logs.value.filter(l => `${l.message} ${l.app}`.includes(query.value) && (filter.value==='all'||l.level===filter.value)));
const period = ref('7');
const chartData = computed(() => ({ labels:period.value==='7'?['10/30','10/31','11/01','11/02','11/03','11/04','11/05']:['10/23','10/25','10/27','10/29','10/31','11/02','11/05'],datasets:[{label:'请求量（示例）',data:period.value==='7'?[3800,5100,4400,6800,5600,8200,7300]:[6800,9100,7400,10800,9600,12200,9300],fill:true,backgroundColor:isDarkTheme.value?'#10b98122':'#10b98116',borderColor:'#10b981',tension:.35,borderWidth:2,pointRadius:3}]}));
const chartOptions = computed(() => ({maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color:isDarkTheme.value?'#94a3b8':'#64748b'}},y:{grid:{color:isDarkTheme.value?'#334155':'#eef2f6'},ticks:{color:isDarkTheme.value?'#94a3b8':'#64748b'}}}}));
async function run(t) { await runDemoTask(t); toast.add({severity:'success',summary:'模拟执行完成',detail:t.name,life:3000}); }
function createTask(){if(draft.name.trim().length<2){errors.value='请输入至少 2 个字的任务名称';return;}tasks.value.unshift({id:Date.now(),name:draft.name.trim(),description:'新建演示任务',app:draft.app,schedule:draft.schedule,status:'paused',lastRun:'尚未执行',duration:'—',enabled:false});createOpen.value=false;draft.name='';errors.value='';toast.add({severity:'success',summary:'演示任务已创建',life:3000});}
function upload(e){if(e.files.some(f=>f.size>100*1024*1024)){toast.add({severity:'error',summary:'单个文件不能超过 100 MB',life:3000});return;}for(const file of e.files){const type=file.type.startsWith('image/')?'image':file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'document';resources.value.unshift({id:crypto.randomUUID(),name:file.name,type,size:`${Math.ceil(file.size/1024)} KB`,date:'刚刚',tag:'本地文件',local:true,url:URL.createObjectURL(file)});}uploadOpen.value=false;toast.add({severity:'success',summary:'已加入本地文件',detail:'文件没有上传到服务器。',life:3000});}
function preview(r){selected.value=r;previewOpen.value=true;}
function save(){if(!settings.name.trim()){errors.value='请输入工作空间名称';return;}if(!validDemoRetention(settings.retention)){errors.value='保留天数应为 1–90 的整数';return;}try{localStorage.setItem('workerkit-prime-settings',JSON.stringify(settings));errors.value='';toast.add({severity:'success',summary:'演示设置已保存',detail:'保存在当前浏览器。',life:3000});}catch{toast.add({severity:'error',summary:'浏览器存储不可用',life:3000});}}
function exportLogs(){const url=URL.createObjectURL(new Blob([JSON.stringify(filteredLogs.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='workerkit-demo-logs.json';a.click();URL.revokeObjectURL(url);}
</script>

<template>
  <div>
    <div class="demo-heading"><div><h1>{{ names[route.path] }}</h1><p>{{ descriptions[route.path] }}</p></div><Button v-if="activePath==='/'" label="查看任务" icon="pi pi-arrow-up-right" severity="secondary" outlined @click="router.push('/tasks')" /><Button v-if="activePath==='/tasks'" label="新建任务" icon="pi pi-plus" @click="createOpen=true" /><Button v-if="activePath==='/components/preview'" label="添加文件" icon="pi pi-upload" @click="uploadOpen=true" /><Button v-if="activePath==='/logs'" label="导出日志" icon="pi pi-download" severity="secondary" outlined @click="exportLogs" /></div>
    <ComponentExperience v-if="componentPage && !componentPage.example && componentPage.key !== 'preview'" :kind="componentPage.key" />
    <template v-if="activePath==='/'">
      <div class="grid grid-cols-2 xl:grid-cols-4 gap-5 mb-6"><div v-for="stat in [{label:'Worker 应用',value:'8',unit:'个',note:'7 个正常 · 1 个需关注',icon:'pi-box'},{label:'今日任务执行',value:'124',unit:'次',note:'较昨日增加 18 次',icon:'pi-sitemap'},{label:'任务成功率',value:'98.4',unit:'%',note:'122 次成功 · 2 次异常',icon:'pi-check-circle'},{label:'资源存储',value:'1.28',unit:'GB',note:'已使用配额的 12.8%',icon:'pi-database'}]" :key="stat.label" class="card"><div class="flex justify-between text-muted-color"><span>{{ stat.label }}</span><i :class="`pi ${stat.icon}`" /></div><p class="mt-5 mb-3 text-3xl font-semibold">{{ stat.value }}<span class="text-sm font-normal ml-2 text-muted-color">{{ stat.unit }}</span></p><p class="text-xs text-muted-color">{{ stat.note }}</p></div></div>
      <div class="grid xl:grid-cols-[minmax(0,1.8fr)_minmax(280px,1fr)] gap-6 mb-6"><div class="card"><div class="flex items-center justify-between gap-3"><div><h2 class="text-base font-semibold mb-1">请求趋势</h2><p class="text-xs text-muted-color">各应用请求量的示例分布</p></div><Select v-model="period" :options="[{label:'近 7 天',value:'7'},{label:'近 14 天',value:'14'}]" option-label="label" option-value="value" aria-label="趋势时间范围" /></div><div class="flex items-center gap-3 my-5"><span class="text-2xl font-semibold">{{ period==='7'?'31,702':'64,518' }}</span><span class="text-xs text-muted-color">次请求</span><Tag value="+12.6%" severity="success" /></div><Chart type="line" :data="chartData" :options="chartOptions" class="h-56" /></div><div class="card"><h2 class="text-base font-semibold mb-1">服务状态</h2><p class="text-xs text-muted-color mb-6">常用应用一览 · 示例</p><div class="space-y-6"><div v-for="service in services" :key="service.slug" class="flex items-center gap-3"><Avatar :label="service.name[0]" size="large" shape="circle" /><div class="flex-1"><p class="font-medium">{{ service.name }}</p><p class="text-xs text-muted-color mt-1">{{ service.description }}</p></div><Tag :value="service.status" :severity="service.status==='正常'?'success':'warn'" /></div></div></div></div>
      <div class="card"><div class="flex justify-between items-center mb-5"><h2 class="text-base font-semibold">最近执行</h2><Button label="全部任务" icon="pi pi-arrow-right" icon-pos="right" text severity="secondary" size="small" @click="router.push('/tasks')" /></div><DataTable :value="tasks.slice(0,4)"><Column field="name" header="任务名称" /><Column field="app" header="应用" /><Column field="lastRun" header="上次执行" /><Column field="duration" header="耗时" /><Column header="结果"><template #body="{data}"><Tag :value="statuses[data.status][0]" :severity="statuses[data.status][1]" /></template></Column></DataTable></div>
    </template>
    <template v-if="activePath==='/tasks'">
      <div class="card"><div class="flex justify-between gap-3 flex-wrap mb-5"><InputText v-model="query" placeholder="搜索任务或应用…" aria-label="搜索任务" class="w-full sm:w-72" /><Select v-model="filter" :options="[{label:'全部计划',value:'all'},{label:'已启用',value:'enabled'},{label:'已暂停',value:'paused'}]" option-label="label" option-value="value" aria-label="任务状态筛选" /></div><DataTable :value="filteredTasks" paginator :rows="2" data-key="id" striped-rows><template #empty><div class="p-6 text-center">没有匹配的任务</div></template><Column field="name" header="任务名称" sortable><template #body="{data}"><p class="font-medium whitespace-nowrap">{{ data.name }}</p><p class="text-xs text-muted-color mt-1">{{ data.description }}</p></template></Column><Column field="app" header="应用" sortable /><Column field="schedule" header="执行计划" /><Column header="最近结果"><template #body="{data}"><Tag :value="statuses[data.status][0]" :severity="statuses[data.status][1]" /></template></Column><Column field="lastRun" header="上次执行" /><Column header="启用"><template #body="{data}"><ToggleSwitch v-model="data.enabled" :disabled="data.status==='running'" :aria-label="`启用${data.name}`" /></template></Column><Column header="操作"><template #body="{data}"><Button label="运行" icon="pi pi-play" text size="small" :loading="data.status==='running'" :aria-label="`运行${data.name}`" @click="run(data)" /></template></Column></DataTable></div><Message severity="secondary" class="mt-5">本页只模拟任务状态；执行结果会出现在运行日志中，刷新后任务恢复初始示例。</Message>
    </template>
    <template v-if="activePath==='/components/preview'">
      <div class="flex justify-between gap-4 flex-wrap mb-6"><SelectButton v-model="filter" :allow-empty="false" :options="[{label:'全部资源',value:'all'},{label:'图片',value:'image'},{label:'视频',value:'video'},{label:'音频',value:'audio'},{label:'文档',value:'document'}]" option-label="label" option-value="value" /><InputText v-model="query" placeholder="搜索资源…" aria-label="搜索资源" /></div>
      <div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-5"><div v-for="r in filteredResources" :key="r.id" class="card !p-0 overflow-hidden"><button class="demo-resource-preview" :aria-label="`预览${r.name}`" @click="preview(r)"><img v-if="r.type==='image' && r.url" :src="r.url" :alt="r.name" /><i v-else :class="`pi ${types[r.type][1]}`" /></button><div class="p-5"><div class="flex justify-between items-center gap-3"><button class="font-medium text-left truncate" @click="preview(r)">{{ r.name }}</button><Tag :value="types[r.type][0]" severity="secondary" /></div><p class="text-xs text-muted-color mt-2">{{ r.size }} · {{ r.date }}</p><div class="flex justify-between items-center mt-4"><span class="text-xs text-muted-color">{{ r.tag }}</span><Button label="预览" icon="pi pi-eye" text size="small" @click="preview(r)" /></div></div></div></div><Message v-if="!filteredResources.length" severity="secondary">没有匹配的资源</Message><p class="text-xs text-muted-color mt-6">{{ filteredResources.length }} 个资源 · 示例媒体可播放，本地文件不会上传到服务器。</p>
    </template>
    <template v-if="activePath==='/logs'">
      <Message severity="warn" class="mb-6">示例异常：示例上游请求超时，已有缓存仍可使用。</Message><div class="card"><div class="flex justify-between gap-3 flex-wrap mb-5"><InputText v-model="query" placeholder="搜索日志或应用…" aria-label="搜索日志" class="w-full sm:w-80" /><Select v-model="filter" :options="[{label:'全部级别',value:'all'},{label:'信息',value:'info'},{label:'警告',value:'warn'},{label:'错误',value:'error'}]" option-label="label" option-value="value" aria-label="日志级别筛选" /></div><DataTable :value="filteredLogs" paginator :rows="10"><template #empty>没有符合条件的日志</template><Column field="time" header="时间" /><Column header="级别"><template #body="{data}"><Tag :value="{info:'信息',warn:'警告',error:'错误'}[data.level]" :severity="{info:'info',warn:'warn',error:'danger'}[data.level]" /></template></Column><Column field="app" header="应用" /><Column field="message" header="事件内容" /><Column field="duration" header="耗时" /></DataTable></div>
    </template>
    <form v-if="activePath==='/settings'" class="max-w-4xl space-y-6" @submit.prevent="save">
      <div class="card space-y-5"><h2 class="text-base font-semibold">基本信息</h2><div class="flex flex-col gap-2"><label for="prime-name">工作空间名称</label><InputText id="prime-name" v-model="settings.name" required /></div><div class="flex flex-col gap-2"><label for="prime-description">说明</label><Textarea id="prime-description" v-model="settings.description" :rows="2" /></div><div class="grid sm:grid-cols-2 gap-5"><div class="flex flex-col gap-2"><label for="prime-timezone">显示时区</label><Select input-id="prime-timezone" v-model="settings.timezone" :options="demoTimezones" /></div><div class="flex flex-col gap-2"><label for="prime-retention">日志保留天数</label><InputNumber input-id="prime-retention" v-model="settings.retention" :min="1" :max="90" show-buttons /></div></div></div>
      <div class="card"><h2 class="text-base font-semibold mb-2">通知偏好</h2><p class="text-xs text-muted-color">演示表单，尚未连接消息发送服务</p><div class="demo-setting-row"><label for="prime-failure">任务失败提醒</label><ToggleSwitch input-id="prime-failure" v-model="settings.failureNotice" /></div><div class="demo-setting-row"><label for="prime-daily">每日运行摘要</label><ToggleSwitch input-id="prime-daily" v-model="settings.dailyDigest" /></div></div><Message v-if="errors" severity="error">{{ errors }}</Message><div class="flex justify-between items-center gap-3"><span class="text-xs text-muted-color">仅保存到当前浏览器</span><Button type="submit" label="保存设置" icon="pi pi-check" /></div>
    </form>
    <Dialog v-model:visible="createOpen" modal header="新建演示任务" :style="{width:'480px',maxWidth:'calc(100vw - 32px)'}"><form class="space-y-5 pt-2" @submit.prevent="createTask"><div class="flex flex-col gap-2"><label for="prime-task-name">任务名称</label><InputText id="prime-task-name" v-model="draft.name" placeholder="例如：每日数据同步" /></div><div class="flex flex-col gap-2"><label for="prime-task-app">所属应用</label><Select input-id="prime-task-app" v-model="draft.app" :options="['demo-api','demo-content','demo-jobs','demo-storage','demo-reports','demo-assets']" /></div><div class="flex flex-col gap-2"><label for="prime-task-schedule">执行计划</label><Select input-id="prime-task-schedule" v-model="draft.schedule" :options="['每天 09:00','每天 15:45','每 30 分钟','每 6 小时']" /></div><Message v-if="errors" severity="error">{{ errors }}</Message><div class="flex justify-end gap-2"><Button label="取消" severity="secondary" outlined @click="createOpen=false" /><Button label="创建任务" type="submit" /></div></form></Dialog>
    <Dialog v-model:visible="uploadOpen" modal header="添加本地文件" :style="{width:'600px',maxWidth:'calc(100vw - 32px)'}"><Message severity="secondary" class="mb-4">文件仅用于浏览器预览，不会发送到服务器。</Message><FileUpload name="demo-files" multiple custom-upload :max-file-size="104857600" choose-label="选择文件" upload-label="加入资源库" cancel-label="清空" @uploader="upload"><template #empty><p class="p-8 text-center text-muted-color">拖入文件，或点击选择 · 单个文件不超过 100 MB</p></template></FileUpload></Dialog>
    <Dialog v-model:visible="previewOpen" modal :header="selected?.name" :style="{width:'720px',maxWidth:'calc(100vw - 32px)'}"><template v-if="selected"><img v-if="selected.type==='image'&&selected.url" :src="selected.url" :alt="selected.name" class="w-full max-h-[60vh] object-contain" /><video v-else-if="selected.type==='video'&&selected.url" :src="selected.url" controls preload="metadata" class="w-full" /><audio v-else-if="selected.type==='audio'&&selected.url" :src="selected.url" controls class="w-full my-6" /><Message v-else severity="secondary">文档元数据示例 · {{ selected.size }} · {{ selected.tag }}</Message></template></Dialog>
  </div>
</template>
